/**
 * In-app notifications (server-generated by triggers/RPCs; one row per
 * recipient, de-duplicated by key). RLS shows only your own, and only for
 * maps you can still access. A realtime subscription refreshes the list.
 */
import { useEffect } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { requireSupabase, supabase, unwrap } from '@/lib/supabase';
import { useAuth } from '@/app/AuthProvider';
import { useWorkspace } from '@/features/workspace/WorkspaceProvider';

export type NotificationKind = 'shared_pin_added' | 'meetup_created' | 'meetup_rescheduled' | 'meetup_cancelled' | 'meetup_joined'
  | 'chess_challenge' | 'chess_accepted' | 'chess_your_turn' | 'chess_finished';
export interface AtlasNotification {
  id: string; kind: NotificationKind; title: string; actorName: string | null;
  collabMapId: string | null; sharedPinId: string | null; meetupId: string | null; chessGameId: string | null; readAt: string | null; createdAt: string;
}
const KEY = ['notifications'] as const;
type Row = Record<string, unknown>;

export function useNotifications() {
  const { user } = useAuth();
  const ws = useWorkspace();
  const qc = useQueryClient();
  const enabled = !!user && !ws.local;

  useEffect(() => {
    if (!enabled || !supabase) return;
    const sb = supabase;
    const ch = sb.channel(`notifications:${user!.id}`)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'notifications', filter: `user_id=eq.${user!.id}` },
        () => void qc.invalidateQueries({ queryKey: KEY }))
      .subscribe((s) => { if (s === 'SUBSCRIBED') void qc.invalidateQueries({ queryKey: KEY }); });
    return () => { void sb.removeChannel(ch); };
  }, [enabled, user, qc]);

  return useQuery({
    queryKey: KEY,
    enabled,
    queryFn: async (): Promise<AtlasNotification[]> => {
      const rows = unwrap(await requireSupabase().from('notifications')
        .select('id, kind, title, collab_map_id, shared_pin_id, meetup_id, chess_game_id, read_at, created_at, actor:profiles!notifications_actor_id_fkey(username, display_name)')
        .order('created_at', { ascending: false }).limit(30));
      // Defensive de-duplication by id (realtime + refetch races).
      const seen = new Set<string>();
      return (rows as Row[]).filter((r) => !seen.has(String(r.id)) && seen.add(String(r.id))).map((r) => {
        const a = r.actor as Row | null;
        return {
          id: String(r.id), kind: r.kind as NotificationKind, title: String(r.title),
          actorName: a ? String(a.display_name || a.username) : null,
          collabMapId: (r.collab_map_id as string) ?? null, sharedPinId: (r.shared_pin_id as string) ?? null,
          meetupId: (r.meetup_id as string) ?? null, chessGameId: (r.chess_game_id as string) ?? null, readAt: (r.read_at as string) ?? null, createdAt: String(r.created_at),
        };
      });
    },
  });
}

export function useMarkNotificationsRead() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (ids: string[]) => {
      if (!ids.length) return;
      unwrap(await requireSupabase().from('notifications').update({ read_at: new Date().toISOString() }).in('id', ids).select('id'));
    },
    onSettled: () => qc.invalidateQueries({ queryKey: KEY }),
  });
}
